import React, { useState, useRef, useCallback, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState([]);
  const [result, setResult] = useState(null);
  const [capturedImage, setCapturedImage] = useState(null); // NEW: pour afficher l'image capturée

  // ================= CAMÉRA =================
  useEffect(() => {
    const startCamera = async () => {
      try {
        pushStatus("🎥 Démarrage de la caméra...");
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user", width: 1280, height: 720 }
        });
        streamRef.current = stream;
        if (videoRef.current) videoRef.current.srcObject = stream;
        pushStatus("✅ Caméra démarrée avec succès");
      } catch (err) {
        pushStatus("❌ Impossible d'accéder à la caméra");
        console.error(err);
      }
    };
    startCamera();

    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const pushStatus = (msg) => {
    setStatus(prev => [...prev, msg]);
  };

  const resetStatus = () => setStatus([]);

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    if (videoRef.current) videoRef.current.srcObject = null;
    pushStatus("📴 Caméra arrêtée");
  };

  // ================= CAPTURE + RECONNAISSANCE =================
  const handleCapture = useCallback(async () => {
    if (!videoRef.current) return;

    setLoading(true);
    resetStatus();
    setResult(null);

    try {
      pushStatus("📸 Étape 1/4 : Capture de l'image depuis la vidéo...");

      const canvas = document.createElement("canvas");
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL("image/jpeg", 0.92); // Qualité 92%

      // NEW: log et affichage direct
      console.log("Image capturée, longueur base64:", imageBase64.length);
      console.log("Préfixe:", imageBase64.substring(0, 30));
      setCapturedImage(imageBase64);

      pushStatus("🚀 Étape 2/4 : Envoi de l'image au Backend (détection + reconnaissance)...");

      const response = await attendanceAPI.recognize(imageBase64);

      pushStatus("📥 Étape 3/4 : Réponse reçue du Backend");

      const data = response?.data || response || {};
      const name = data.student || data.student_name || data.name || "Inconnu";
      let confidence = Number(data.confidence || data.similarity || 0);
      const confidencePercent = (confidence * 100).toFixed(1);

      pushStatus(`🔍 Similarité brute : ${confidence.toFixed(4)}`);

      if ((data.success || confidence > 0.35) && name !== "Inconnu") {
        pushStatus(`✅ Étape 4/4 : Reconnu ! ${name} - ${confidencePercent}%`);
        setResult({
          name,
          confidence: confidencePercent,
          studentId: data.student_id || data.id || "N/A",
          similarity: confidence.toFixed(4),
          time: new Date().toLocaleTimeString()
        });
      } else {
        pushStatus(`⚠️ Étape 4/4 : Non reconnu (similarité trop faible ou aucun visage détecté)`);
        setResult({
          name: "Inconnu",
          confidence: confidencePercent,
          studentId: "N/A",
          similarity: confidence.toFixed(4),
          time: new Date().toLocaleTimeString()
        });
      }
    } catch (err) {
      const errorMsg = err?.response?.data?.error || err?.message || "Erreur inconnue";
      pushStatus(`❌ Erreur lors de la reconnaissance : ${errorMsg}`);
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, []);

  // ================= UI =================
  return (
    <div style={{ padding: 30, maxWidth: 900, margin: "auto", textAlign: "center", fontFamily: "Arial, sans-serif" }}>
      <h2>📷 Reconnaissance Faciale - Test Capture</h2>

      <div style={{ background: "#000", borderRadius: 12, overflow: "hidden", marginBottom: 20 }}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={{ width: "100%", maxHeight: "500px" }}
        />
      </div>

      <div style={{ display: "flex", gap: 12, marginBottom: 20 }}>
        <button
          onClick={handleCapture}
          disabled={loading}
          style={{
            flex: 1,
            padding: 16,
            background: loading ? "#666" : "#4F46E5",
            color: "white",
            border: 0,
            borderRadius: 10,
            fontSize: 16,
            cursor: loading ? "not-allowed" : "pointer"
          }}
        >
          {loading ? "⏳ Analyse en cours..." : "🔍 Capturer & Reconnaître"}
        </button>

        <button
          onClick={stopCamera}
          style={{
            flex: 1,
            padding: 16,
            background: "#EF4444",
            color: "white",
            border: 0,
            borderRadius: 10,
            fontSize: 16
          }}
        >
          🛑 Arrêter la caméra
        </button>
      </div>

      {/* Status Log */}
      <div style={{
        marginTop: 20,
        padding: 15,
        background: "#F3F4F6",
        borderRadius: 10,
        textAlign: "left",
        maxHeight: "300px",
        overflowY: "auto",
        fontSize: 14
      }}>
        {status.map((s, i) => (
          <div key={i} style={{ marginBottom: 6 }}>{s}</div>
        ))}
      </div>

      {/* Image capturée */}
      {capturedImage && (
        <div style={{ marginTop: 20 }}>
          <h3>🖼️ Image capturée :</h3>
          <img src={capturedImage} alt="capture test" style={{ width: "200px", borderRadius: "8px" }} />
        </div>
      )}

      {/* Result */}
      {result && (
        <div style={{
          marginTop: 20,
          padding: 20,
          background: result.name === "Inconnu" ? "#FEE2E2" : "#E0E7FF",
          borderRadius: 12,
          textAlign: "left",
          border: result.name === "Inconnu" ? "1px solid #F87171" : "1px solid #6366F1"
        }}>
          <h3>{result.name === "Inconnu" ? "❌ Non reconnu" : "✅ Étudiant reconnu"}</h3>
          <p><strong>👤 Nom :</strong> {result.name}</p>
          <p><strong>🎯 Confiance :</strong> {result.confidence}% (similarité : {result.similarity})</p>
          <p><strong>🆔 ID :</strong> {result.studentId}</p>
          <p><strong>🕒 Heure :</strong> {result.time}</p>
        </div>
      )}
    </div>
  );
};

export default CameraRecognition;
